const syncTickets = async client => {
 const kept = new Map(); let skipped = 0; let duplicates = 0; let cursor = null;
 do {
  let page; let retries = 0;
  while (true) {
   try { page = await client.listTickets(cursor); break; }
   catch (e) { if (!e || e.status !== 429 || retries === 3) throw e; retries++; await sleep(e.retryAfterMs); }
  }
  for (const ticket of page.tickets) {
   const id = typeof ticket.id === 'string' ? ticket.id.trim() : '';
   const customerId = typeof ticket.customerId === 'string' ? ticket.customerId.trim() : '';
   if (!id || !customerId) { skipped++; continue; }
   if (kept.has(id)) { duplicates++; continue; }
   kept.set(id, {id,customerId,subject:ticket.subject});
  }
  cursor = page.nextCursor;
 } while (cursor !== null);
 const records = Array.from(kept.values()).sort((a,b)=>a.id<b.id?-1:a.id>b.id?1:0);
 return {records,skipped,duplicates};
};
